#include "fault_recovery_adapter_baseline.hpp"
namespace bluesky::fault { std::string FaultRecoveryAdapterBaseline::getSourceId() const { return "SRC-19"; } FaultRecoveryState FaultRecoveryAdapterBaseline::getState() const { return state_; } FaultEvent FaultRecoveryAdapterBaseline::readEvent() const { FaultEvent e; e.sourceId=getSourceId(); e.state=state_; e.quality=FaultQuality::Valid; e.valid=true; return e; } FaultRecoveryResult FaultRecoveryAdapterBaseline::acceptEvent(const FaultEvent& event) { FaultRecoveryResult r; if (event.sourceId != getSourceId()) { r.error=FaultRecoveryError::InvalidData; r.reason="source_id_mismatch"; return r; } if (!event.valid || event.quality==FaultQuality::Invalid) { r.error=FaultRecoveryError::InvalidData; r.reason="invalid_event"; return r; } if (event.stale || event.quality==FaultQuality::Stale) { r.error=FaultRecoveryError::StaleData; r.reason="stale_event"; return r; } state_=event.state; r.accepted=true; return r; } }
